import pandas as pd


def _null_aware_equal(a, b):
    a_na = pd.isna(a)
    b_na = pd.isna(b)
    if a_na and b_na:
        return True
    if a_na or b_na:
        return False
    return a == b


def _pick_latest(group: pd.DataFrame) -> pd.Series:
    # Sort by update_date desc, then email desc, then tier desc (tie-break: greater pair wins)
    g = group.sort_values(
        by=["update_date", "email", "tier"],
        ascending=[False, False, False],
        kind="mergesort",  # stable sort
    )
    return g.iloc[0]


def run(inputs: dict) -> dict:
    dim_acct = inputs["DIM_ACCT"].copy()
    stg_acct = inputs["STG_ACCT"].copy()

    # Ensure expected columns exist even if input is empty
    dim_cols = ["acct_id", "email", "tier", "eff_start_date", "eff_end_date", "is_current"]
    for c in dim_cols:
        if c not in dim_acct.columns:
            dim_acct[c] = pd.Series(dtype="object")

    stg_cols = ["acct_id", "email", "tier", "update_date"]
    for c in stg_cols:
        if c not in stg_acct.columns:
            stg_acct[c] = pd.Series(dtype="object")

    # Step 1: Dedup STG_ACCT to latest per acct_id by update_date,
    # ties broken by greater (email, tier) lexicographic pair.
    if len(stg_acct) == 0:
        stg_dedup = stg_acct.copy()
    else:
        stg_dedup = (
            stg_acct.groupby("acct_id", group_keys=False)
            .apply(_pick_latest)
            .reset_index(drop=True)
        )

    # Build mutable list of dicts representing DIM_ACCT rows
    rows = dim_acct.to_dict("records")

    # Process each staged record (order across different acct_ids does not matter,
    # since each acct_id is handled independently)
    for _, s in stg_dedup.iterrows():
        acct_id = s["acct_id"]
        s_email = s["email"]
        s_tier = s["tier"]
        s_update_date = s["update_date"]

        # Find current row (is_current == 1) for this acct_id
        current_idx = None
        for i, r in enumerate(rows):
            if r.get("acct_id") == acct_id and r.get("is_current") == 1:
                current_idx = i
                break

        if current_idx is None:
            # No current row exists: insert new current version
            new_row = {
                "acct_id": acct_id,
                "email": s_email,
                "tier": s_tier,
                "eff_start_date": s_update_date,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            }
            rows.append(new_row)
        else:
            c = rows[current_idx]

            tier_changed = not _null_aware_equal(c.get("tier"), s_tier)
            email_changed = not _null_aware_equal(c.get("email"), s_email)

            if tier_changed:
                # Expire old current row
                rows[current_idx]["eff_end_date"] = s_update_date
                rows[current_idx]["is_current"] = 0

                # Insert new current version
                new_row = {
                    "acct_id": acct_id,
                    "email": s_email,
                    "tier": s_tier,
                    "eff_start_date": s_update_date,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                }
                rows.append(new_row)

            if email_changed:
                # Retro-overwrite email across ALL rows (history and current) for this acct_id
                for r in rows:
                    if r.get("acct_id") == acct_id:
                        r["email"] = s_email

    out = pd.DataFrame(rows, columns=dim_cols)

    # Normalize dtypes where possible
    if len(out) > 0:
        out["is_current"] = out["is_current"].astype("int64")
        try:
            out["acct_id"] = out["acct_id"].astype(dim_acct["acct_id"].dtype)
        except Exception:
            pass

    return {"dim_acct_out": out}
